INSERT INTO `templates` (`language`, `id`, `key_word`, `name`, `last_modified`) VALUES ('af','1','EMAIL_ACTIVATE','Dankie dat jy aangesluit het.<br>Volg asseblief die skakel om jou rekening te aktiveer.<br><br><a href=\"{{confirm_url}}\">Bevestig e-pos</a><br><br>Vroeër!','2023-11-29 06:25:32'),('am','1','EMAIL_ACTIVATE','ስለተመዘገቡ እናመሰግናለን።<br>እባክዎ መለያዎን ለማግበር አገናኙን ይከተሉ።<br><br><a href=\"{{confirm_url}}\">ኢሜል አረጋግጥ</a><br><br>ቺርስ!','2023-11-29 06:25:36'),('ar','1','EMAIL_ACTIVATE','شكرًا على الاشتراك.<br>يُرجى اتباع الرابط لتنشيط حسابك.<br><br><a href=\"{{confirm_url}}\">تأكيد البريد الإلكتروني</a><br><br>تحية!','2023-11-29 06:25:39'),('az','1','EMAIL_ACTIVATE','Qeydiyyatdan keçdiyiniz üçün təşəkkür edirik.<br>Hesabınızı aktivləşdirmək üçün linkə daxil olun.<br><br><a href=\"{{confirm_url}}\">E-poçtu təsdiqləyin</a><br><br>Sağ olun!','2023-11-29 06:25:42'),('be','1','EMAIL_ACTIVATE','Дзякуй за рэгістрацыю.<br>Калі ласка, перайдзіце па спасылцы, каб актываваць свой уліковы запіс.<br><br><a href=\"{{confirm_url}}\">Пацвердзіце адрас электроннай пошты</a><br><br>Вітаем!','2023-11-29 06:25:46'),('bg','1','EMAIL_ACTIVATE','Благодаря, че се регистрирахте. <br> Моля, следвайте връзката, за да активирате акаунта си. <br>  <br>  <a href=\"{{confirm_url}}\"> Потвърдете имейл </a>  <br>  <br> Наздраве! ','2021-11-25 03:37:03'),('bn','1','EMAIL_ACTIVATE','সাইন আপ করার জন্য ধন্যবাদ. <br> আপনার অ্যাকাউন্ট সক্রিয় করতে লিঙ্ক অনুসরণ করুন. <br>  <br>  <a href=\"{{confirm_url}}\"> নিশ্চিত ইমেইল </a>  <br>  <br> চিয়ার্স! ','2021-11-25 03:37:07'),('bs','1','EMAIL_ACTIVATE','Hvala što ste se prijavili. <br> Molimo slijedite link da aktivirate svoj račun. <br>  <br>  <a href=\"{{confirm_url}}\"> potvrdi email </a>  <br>  <br> Živjeli! ','2021-11-25 03:37:13'),('ca','1','EMAIL_ACTIVATE','Gràcies per registrar-te. <br> Si us plau, seguiu l\'enllaç per activar el vostre compte. <br>  <br>  <a href=\"{{confirm_url}}\"> Confirma el correu electrònic </a>  <br>  <br> Salut! ','2021-11-25 03:37:17'),('ceb','1','EMAIL_ACTIVATE','Salamat sa pagpirma. <br> Palihug sundan ang link aron ma-aktibo ang imong account. <br>  <br>  <a href=\"{{confirm_url}}\"> Kumpirma ang Email </a>  <br>  <br> Cheers! ','2021-11-25 03:37:24'),('co','1','EMAIL_ACTIVATE','Grazie per esse registratu. <br> Per piacè seguite u ligame per attivà u vostru contu. <br>  <br>  <a href=\"{{confirm_url}}\"> Cunfirmà e-mail </a>  <br>  <br> A salute! ','2021-11-25 03:37:30'),('cs','1','EMAIL_ACTIVATE','Děkujeme za přihlášení. <br> Kliknutím na odkaz aktivujte svůj účet. <br>  <br>  <a href=\"{{confirm_url}}\"> potvrdit email </a>  <br>  <br> Na zdraví! ','2021-11-25 03:37:35'),('cy','1','EMAIL_ACTIVATE','Diolch am arwyddo. <br> Dilynwch y ddolen i actifadu\'ch cyfrif. <br>  <br>  <a href=\"{{confirm_url}}\"> Cadarnhau Ebost </a>  <br>  <br> Lloniannau! ','2021-11-25 03:37:42'),('da','1','EMAIL_ACTIVATE','Tak for din tilmelding. <br> Følg linket for at aktivere din konto. <br>  <br>  <a href=\"{{confirm_url}}\"> Bekræft Email </a>  <br>  <br> Skål! ','2021-11-25 03:37:48'),('de','1','EMAIL_ACTIVATE','Danke für\'s Registrieren. <br> Bitte folgen Sie dem Link, um Ihr Konto zu aktivieren. <br>  <br>  <a href=\"{{confirm_url}}\"> Bestätigungs-E-Mail </a>  <br>  <br> Danke schön! ','2021-11-25 03:37:51'),('el','1','EMAIL_ACTIVATE','Ευχαριστώ για την εγγραφή σας. <br> Ακολουθήστε τον σύνδεσμο για να ενεργοποιήσετε τον λογαριασμό σας. <br>  <br>  <a href=\"{{confirm_url}}\"> Επιβεβαίωση διεύθυνσης ηλεκτρονικού ταχυδρομείου </a>  <br>  <br> Στην υγειά σας! ','2021-11-25 03:37:57'),('en','1','EMAIL_ACTIVATE','Thanks for signing up.<br>Please follow the link to activate your account.<br><br><a href=\"{{confirm_url}}\">Confirm Email</a><br><br>Cheers!','2020-11-25 03:37:57'),('eo','1','EMAIL_ACTIVATE','Dankon pro registriĝo. <br> Bonvolu sekvi la ligilon por aktivigi vian konton. <br>  <br>  <a href=\"{{confirm_url}}\"> Konfirmi Retpoŝtadreson </a>  <br>  <br> Saluton! ','2021-11-25 03:54:49'),('es','1','EMAIL_ACTIVATE','Gracias por registrarte. <br> Siga el enlace para activar su cuenta. <br>  <br>  <a href=\"{{confirm_url}}\"> Confirmar correo electrónico </a>  <br>  <br> ¡Salud! ','2021-11-25 03:54:49'),('et','1','EMAIL_ACTIVATE','Täname registreerumast. <br> Konto aktiveerimiseks järgige linki. <br>  <br>  <a href=\"{{confirm_url}}\"> Kinnita email </a>  <br>  <br> Tervist! ','2021-11-25 03:54:49'),('eu','1','EMAIL_ACTIVATE','Eskerrik asko izena emateagatik. <br> Mesedez, jarraitu esteka zure kontua aktibatzeko. <br>  <br>  <a href=\"{{confirm_url}}\"> Berretsi E-posta </a>  <br>  <br> Animo! ','2021-11-25 03:54:49'),('fa','1','EMAIL_ACTIVATE','از ثبت نام شما سپاسگزاریم. <br> لطفا لینک را دنبال کنید تا حساب خود را فعال کنید. <br>  <br>  <a href=\"{{confirm_url}}\"> ایمیل تایید </a>  <br>  <br> به سلامتی! ','2021-11-25 03:54:49'),('fi','1','EMAIL_ACTIVATE','Kiitos rekisteröitymisestä. <br> Aktivoi tilisi klikkaamalla linkkiä. <br>  <br>  <a href=\"{{confirm_url}}\"> vahvista sähköposti </a>  <br>  <br> Kippis! ','2021-11-25 03:54:49'),('fr','1','EMAIL_ACTIVATE','Merci pour l\'enregistrement. <br> Veuillez suivre le lien pour activer votre compte. <br>  <br>  <a href=\"{{confirm_url}}\"> Confirmez votre email </a>  <br>  <br> À votre santé! ','2021-11-25 03:54:49'),('fy','1','EMAIL_ACTIVATE','Tank foar it oanmelden. <br> Folgje asjebleaft de keppeling om jo akkount te aktivearjen. <br>  <br>  <a href=\"{{confirm_url}}\"> Befêstigje e-mail </a>  <br>  <br> Tsjoch! ','2021-11-25 03:54:49'),('ga','1','EMAIL_ACTIVATE','Go raibh maith agat as síniú suas. <br> Lean an nasc chun do chuntas a ghníomhachtú. <br>  <br>  <a href=\"{{confirm_url}}\"> Deimhnigh Ríomhphost </a>  <br>  <br> Cheers! ','2021-11-25 03:54:49'),('gd','1','EMAIL_ACTIVATE','Taing airson d ’ainm a chuir ris. <br> Feuch an lean thu an ceangal gus do chunntas a ghnìomhachadh. <br>  <br>  <a href=\"{{confirm_url}}\"> Dearbhaich post-d </a>  <br>  <br> Slàinte! ','2021-11-25 03:54:49'),('gl','1','EMAIL_ACTIVATE','Grazas por rexistrarte. <br> Siga a ligazón para activar a súa conta. <br>  <br>  <a href=\"{{confirm_url}}\"> Confirme o correo electrónico </a>  <br>  <br> Saúdos! ','2021-11-25 03:54:49'),('gu','1','EMAIL_ACTIVATE','સાઇન અપ કરવા બદલ આભાર. <br> તમારું એકાઉન્ટ સક્રિય કરવા માટે કૃપા કરીને લિંકને અનુસરો. <br>  <br>  <a href=\"{{confirm_url}}\"> ઇમેઇલ પુષ્ટિ </a>  <br>  <br> ચીયર્સ! ','2021-11-25 03:54:49'),('ha','1','EMAIL_ACTIVATE','Godiya da yin rajista. <br> Da fatan za a bi hanyar haɗin don kunna asusunku. <br>  <br>  <a href=\"{{confirm_url}}\"> Tabbatar da Imel </a>  <br>  <br> Barka da warhaka! ','2021-11-25 03:54:49'),('hi','1','EMAIL_ACTIVATE','साइन अप करने के लिए धन्यवाद। <br> कृपया अपने खाते को सक्रिय करने के लिए लिंक का अनुसरण करें। <br>  <br>  <a href=\"{{confirm_url}}\"> ईमेल की पुष्टि करें </a>  <br>  <br> चीयर्स! ','2021-11-25 03:54:49'),('hmn','1','EMAIL_ACTIVATE','Ua tsaug rau kev tso npe. <br> Thov ua raws qhov txuas mus qhib koj tus account. <br>  <br>  <a href=\"{{confirm_url}}\"> Paub meej Email </a>  <br>  <br> Cheers! ','2021-11-25 03:54:49'),('hr','1','EMAIL_ACTIVATE','Hvala što ste se prijavili. <br> Slijedite vezu kako biste aktivirali svoj račun. <br>  <br>  <a href=\"{{confirm_url}}\"> Potvrdite e-poštu </a>  <br>  <br> Živjeli! ','2021-11-25 03:54:49'),('ht','1','EMAIL_ACTIVATE','Mèsi paske w enskri. <br> Tanpri swiv lyen an pou aktive kont ou. <br>  <br>  <a href=\"{{confirm_url}}\"> Konfime Imèl </a>  <br>  <br> Bonjou! ','2021-11-25 03:54:49'),('hu','1','EMAIL_ACTIVATE','Köszönjük a feliratkozást. <br> Kérjük, kövesse a linket fiókja aktiválásához. <br>  <br>  <a href=\"{{confirm_url}}\"> Megerősítő E-mail </a>  <br>  <br> Egészségére! ','2021-11-25 03:54:49'),('hy','1','EMAIL_ACTIVATE','Շնորհակալություն գրանցվելու համար: <br> Խնդրում ենք հետևել հղմանը` ձեր հաշիվն ակտիվացնելու համար: <br>  <br>  <a href=\"{{confirm_url}}\"> Հաստատեք էլ </a>  <br>  <br> Կեցցե՜ ','2021-11-25 03:54:49'),('id','1','EMAIL_ACTIVATE','Terima kasih telah mendaftar. <br> Silakan ikuti tautan untuk mengaktifkan akun Anda. <br>  <br>  <a href=\"{{confirm_url}}\"> Konfirmasi email </a>  <br>  <br> Bersulang! ','2021-11-25 03:54:49'),('ig','1','EMAIL_ACTIVATE','Daalụ maka ịdebanye aha. <br> Biko soro njikọ a ka ịgbalite akaụntụ gị. <br>  <br>  <a href=\"{{confirm_url}}\"> Kwenye Ozi Ịntanetị </a>  <br>  <br> Ekele! ','2021-11-25 03:54:49'),('is','1','EMAIL_ACTIVATE','Takk fyrir að skrá þig. <br> Vinsamlegast fylgdu hlekknum til að virkja reikninginn þinn. <br>  <br>  <a href=\"{{confirm_url}}\"> Staðfesta tölvupóst </a>  <br>  <br> Skál! ','2021-11-25 03:54:49'),('it','1','EMAIL_ACTIVATE','Grazie per esserti iscritto. <br> Segui il link per attivare il tuo account. <br>  <br>  <a href=\"{{confirm_url}}\"> Conferma email </a>  <br>  <br> Saluti! ','2021-11-25 03:54:49'),('iw','1','EMAIL_ACTIVATE','תודה על ההרשמה. <br> אנא עקוב אחר הקישור כדי להפעיל את חשבונך. <br>  <br>  <a href=\"{{confirm_url}}\"> אשר אימייל </a>  <br>  <br> לחיים! ','2021-11-25 03:54:49'),('ja','1','EMAIL_ACTIVATE','サインアップしていただきありがとうございます。 <br> リンクをたどってアカウントを有効にしてください。 <br>  <br>  <a href=\"{{confirm_url}}\"> Eメール確認 </a>  <br>  <br> 乾杯！ ','2021-11-25 03:54:49'),('jw','1','EMAIL_ACTIVATE','Matur nuwun kanggo mlebu. <br> Mangga tindakake link kanggo ngaktifake akun. <br>  <br>  <a href=\"{{confirm_url}}\"> Konfirmasi Email </a>  <br>  <br> sugeng riyadi! ','2021-11-25 03:54:49'),('ka','1','EMAIL_ACTIVATE','მადლობა დარეგისტრირებისთვის. <br> გთხოვთ, მიჰყევით ბმულს თქვენი ანგარიშის გასააქტიურებლად. <br>  <br>  <a href=\"{{confirm_url}}\"> დაადასტურეთ ელ - ფოსტა </a>  <br>  <br> Გაუმარჯოს! ','2021-11-25 03:54:49'),('kk','1','EMAIL_ACTIVATE','Тіркелгеніңізге рахмет. <br> Тіркелгіңізді белсендіру үшін сілтемеге өтіңіз. <br>  <br>  <a href=\"{{confirm_url}}\"> Электронды Поштаны Растау </a>  <br>  <br> Сәлем! ','2021-11-25 03:54:49'),('km','1','EMAIL_ACTIVATE','អរគុណសម្រាប់ការចុះឈ្មោះ។ <br> សូមធ្វើតាមតំណ ដើម្បីដំណើរការគណនីរបស់អ្នក។ <br>  <br>  <a href=\"{{